SELECT job_title, salary_bucket, min_salary, director_count FROM (SELECT job_title, CASE WHEN salary >= 129000 THEN 'high' WHEN salary >= 74000 THEN 'mid' ELSE 'low' END salary_bucket, MIN(salary) min_salary, SUM(CASE WHEN job_title = 'Director' THEN 1 ELSE 0 END) director_count FROM employees GROUP BY job_title, CASE WHEN salary >= 129000 THEN 'high' WHEN salary >= 74000 THEN 'mid' ELSE 'low' END) s WHERE director_count >= 23 ORDER BY director_count
